/// The PIM wordmark ("Pim"), theme-aware.
class PimLogo extends StatelessWidget {
  const PimLogo({super.key, this.height = 22});

  final double height;

  @override
  Widget build(BuildContext context) {
    final dark = Theme.of(context).brightness == Brightness.dark;
    final svg = dark
        ? _kLogoSvg
        : _kLogoSvg.replaceAll('fill="white"', 'fill="#1B1C15"');
    return SvgPicture.string(
      svg,
      height: height,
      semanticsLabel: 'PIM',
    );
  }
}
